  8→	import { page } from '$app/stores';
  9→	import { onMount, onDestroy } from 'svelte';
 10→	import type { SessionDetail, SessionEvent as SessionEventType } from '$lib/api';
 11→	import { fetchSession, fetchSessionEvents, fetchTasks } from '$lib/api';
 12→	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 13→	import { isStaticMode } from '$lib/stores/mode.svelte';
 14→	import type { BroadcastEvent } from '@kynetic-ai/shared';
 15→	import { parseEventsToBlocks, accumulateStreamingText, getLastSeq, type DisplayBlock } from '$lib/components/session/session-utils';
 16→	import SessionStream from '$lib/components/session/SessionStream.svelte';
 17→	import SessionContextPanel from '$lib/components/session/SessionContextPanel.svelte';
