    40→			error = '';
    41→			return;
    42→		}
    43→
    44→		loading = true;
    45→		error = '';
    46→		try {
    47→			const [sessionData, eventsData] = await Promise.all([
    48→				fetchSession(sessionId),
    49→				fetchSessionEvents(sessionId)
    50→			]);
    51→			session = sessionData;
    52→			events = eventsData.events;
    53→			blocks = parseEventsToBlocks(events);
    54→			lastSeq = getLastSeq(events);
    55→
    56→			// Resolve task title if the session has a task_id
    57→			if (sessionData.task_id) {
    58→				resolveTaskTitle(sessionData.task_id);
    59→			}
    60→		} catch (err) {
    61→			error = err instanceof Error ? err.message : 'Failed to load session';
    62→		} finally {
    63→			loading = false;
    64→		}
    65→	}
    66→
    67→	async function resolveTaskTitle(taskId: string) {
    68→		try {
    69→			const tasksData = await fetchTasks({ limit: 1000 });
    70→			const ref = taskId.startsWith('@') ? taskId : `@${taskId}`;
    71→			for (const task of tasksData.items) {
    72→				if (`@${task._ulid}` === ref) {
    73→					taskTitle = task.title;
    74→					return;
    75→				}
    76→				for (const slug of task.slugs || []) {
    77→					if (`@${slug}` === ref) {
    78→						taskTitle = task.title;
    79→						return;
    80→					}
    81→				}
    82→			}
    83→		} catch {
    84→			// Non-critical — ReferenceLink falls back to raw ID display
    85→		}
    86→	}
    87→
    88→	// AC: @ui-session-stream ac-2 — Periodic structured refresh for live sessions
    89→	async function refreshEvents() {
    90→		if (!isLive) return;
    91→		try {
    92→			const eventsData = await fetchSessionEvents(sessionId, lastSeq);
    93→			if (eventsData.events.length > 0) {
    94→				events = [...events, ...eventsData.events];
    95→				blocks = parseEventsToBlocks(events);
    96→				lastSeq = getLastSeq(events);
    97→				// Clear streaming text when we get structured data
    98→				streamingText = '';
    99→			}
   100→
   101→			// Also refresh session metadata to detect status changes
   102→			const sessionData = await fetchSession(sessionId);
   103→			session = sessionData;
   104→		} catch {
   105→			// Ignore refresh errors — will retry on next interval
   106→		}
   107→	}
   108→
   109→	// AC: @ui-session-stream ac-2 — WebSocket handler for live text chunks
   110→	function handleAgentEvent(event: BroadcastEvent) {
   111→		// Uses extracted utility for session-filtered text accumulation
