   187→	<!-- Loading skeleton -->
   188→	{#if loading}
   189→		<SessionStreamSkeleton />
   190→	{:else if isStaticMode()}
   191→		<div class="mx-4 mt-4 rounded-lg border border-dashed p-6 text-sm text-muted-foreground" data-testid="session-static-message">
