import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: false,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: 1, // Sequential: each test gets its own ephemeral-port daemon
  reporter: process.env.CI ? 'github' : 'html',
  timeout: 30_000,

  expect: {
    timeout: 10_000,
  },

  use: {
    // No baseURL — each test gets a daemon on an ephemeral port via the daemon fixture
    // Tests use daemon.baseUrl for API calls and page.goto(`${daemon.baseUrl}/...`) for navigation
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    actionTimeout: 10_000,
  },

  // No webServer - daemon is started by test fixture (test-base.ts)
  // The daemon serves both the API and the built web UI

  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],

  outputDir: 'test-results',
});

import adapter from '@sveltejs/adapter-static';

// Base path for GitHub Pages deployment (set via BASE_PATH env var)
const basePath = process.env.BASE_PATH || '';

/** @type {import('@sveltejs/kit').Config} */
const config = {
	kit: {
		adapter: adapter({
			// Output directory for static build (to be embedded in daemon)
			pages: 'build',
			assets: 'build',
			// Generate index.html as SPA entry point
			fallback: 'index.html',
			precompress: false,
			strict: true
		}),
		paths: {
			// Set base path for GitHub Pages (empty for daemon/local)
			base: basePath
		}
	}
};

export default config;

