import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests/e2e',
  fullyParallel: false,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: 1, // Sequential: each test gets its own ephemeral-port daemon
  reporter: process.env.CI ? 'github' : 'html',
  timeout: 30_000,

  expect: {
    timeout: 10_000,
  },

  use: {
    // No baseURL — each test gets a daemon on an ephemeral port via the daemon fixture
    // Tests use daemon.baseUrl for API calls and page.goto(`${daemon.baseUrl}/...`) for navigation
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    actionTimeout: 10_000,
  },

  // No webServer - daemon is started by test fixture (test-base.ts)
  // The daemon serves both the API and the built web UI

  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],

  outputDir: 'test-results',
});

import { test, expect } from '../fixtures/test-base';

test.describe('Smoke Tests', () => {
  test('page loads and shows sidebar', async ({ page, daemon }) => {
    await page.goto('/');

    // Sidebar navigation renders the dashboard entry in the desktop shell
    await expect(page.getByTestId('nav-link-dashboard')).toBeVisible();

    // Connection status shows connected
    const connectionStatus = page.getByTestId('connection-status');
    await expect(connectionStatus).toBeVisible();
    await expect(connectionStatus).toContainText(/connected/i);
  });

  test('dashboard page loads with navigation', async ({ page, daemon }) => {
    await page.goto('/');

    // Should see the kspec header
    await expect(page.getByText('kspec').first()).toBeVisible();

    // Should see the Dashboard heading
    await expect(page.getByRole('heading', { name: 'Dashboard' })).toBeVisible();
  });

  test('can load tasks page', async ({ page, daemon }) => {
    // Navigate directly to tasks page
    await page.goto('/tasks');

    // Wait for page to load - check for the heading
    await expect(page.getByRole('heading', { name: 'Tasks' })).toBeVisible();

    // Task list should be visible
    await expect(page.getByTestId('task-list')).toBeVisible({ timeout: 15000 });
  });

  test('can load items page', async ({ page, daemon }) => {
    await page.goto('/items');

    // Wait for page to load - check for the heading
    await expect(page.getByRole('heading', { name: 'Items' })).toBeVisible();
  });

  test('can load inbox page', async ({ page, daemon }) => {
    await page.goto('/inbox');

    // Wait for page to load - check for the heading
    await expect(page.getByRole('heading', { name: 'Inbox' })).toBeVisible();
  });
});

